    "\u{1F926}\u{1F3FF}\u200D\u2640\uFE0F": "\u3072\u305F\u3044\u306B\u624B\u3092\u3042\u3066\u308B\u5973: \u6FC3\u3044\u808C\u8272 \u3042\u3061\u3083\u30FC \u3046\u305D\u3067\u3057\u3087 \u30B8\u30A7\u30B9\u30C1\u30E3\u30FC \u30B7\u30E7\u30C3\u30AF \u3072\u305F\u3044\u306B\u624B \u3072\u305F\u3044\u306B\u624B\u3092\u3042\u3066\u308B\u5973 \u307E\u305F\u304B \u4FE1\u3058\u3089\u308C\u306A\u3044 \u5973 \u5973\u6027 \u6FC3\u3044\u808C\u8272",
    "\u{1F937}": "\u304A\u624B\u4E0A\u3052\u3059\u308B\u4EBA \u304A\u624B\u4E0A\u3052 \u3055\u3042\u306D \u30B8\u30A7\u30B9\u30C1\u30E3\u30FC \u308F\u304B\u308A\u307E\u305B\u3093 \u4EBA \u591A\u5206\u306D \u77E5\u3089\u306A\u3044 \u80A9\u3092\u3059\u304F\u3081\u308B",
    "\u{1F937}\u{1F3FB}": "\u304A\u624B\u4E0A\u3052\u3059\u308B\u4EBA: \u8584\u3044\u808C\u8272 \u304A\u624B\u4E0A\u3052 \u304A\u624B\u4E0A\u3052\u3059\u308B\u4EBA \u3055\u3042\u306D \u30B8\u30A7\u30B9\u30C1\u30E3\u30FC \u308F\u304B\u308A\u307E\u305B\u3093 \u4EBA \u591A\u5206\u306D \u77E5\u3089\u306A\u3044 \u80A9\u3092\u3059\u304F\u3081\u308B \u8584\u3044\u808C\u8272",
    "\u{1F937}\u{1F3FC}": "\u304A\u624B\u4E0A\u3052\u3059\u308B\u4EBA: \u3084\u3084\u8584\u3044\u808C\u8272 \u304A\u624B\u4E0A\u3052 \u304A\u624B\u4E0A\u3052\u3059\u308B\u4EBA \u3055\u3042\u306D \u30B8\u30A7\u30B9\u30C1\u30E3\u30FC \u3084\u3084\u8584\u3044\u808C\u8272 \u308F\u304B\u308A\u307E\u305B\u3093 \u4EBA \u591A\u5206\u306D \u77E5\u3089\u306A\u3044 \u80A9\u3092\u3059\u304F\u3081\u308B",
    "\u{1F937}\u{1F3FD}": "\u304A\u624B\u4E0A\u3052\u3059\u308B\u4EBA: \u4E2D\u9593\u306E\u808C\u8272 \u304A\u624B\u4E0A\u3052 \u304A\u624B\u4E0A\u3052\u3059\u308B\u4EBA \u3055\u3042\u306D \u30B8\u30A7\u30B9\u30C1\u30E3\u30FC \u308F\u304B\u308A\u307E\u305B\u3093 \u4E2D\u9593\u306E\u808C\u8272 \u4EBA \u591A\u5206\u306D \u77E5\u3089\u306A\u3044 \u80A9\u3092\u3059\u304F\u3081\u308B",
    "\u{1F937}\u{1F3FE}": "\u304A\u624B\u4E0A\u3052\u3059\u308B\u4EBA: \u3084\u3084\u6FC3\u3044\u808C\u8272 \u304A\u624B\u4E0A\u3052 \u304A\u624B\u4E0A\u3052\u3059\u308B\u4EBA \u3055\u3042\u306D \u30B8\u30A7\u30B9\u30C1\u30E3\u30FC \u3084\u3084\u6FC3\u3044\u808C\u8272 \u308F\u304B\u308A\u307E\u305B\u3093 \u4EBA \u591A\u5206\u306D \u77E5\u3089\u306A\u3044 \u80A9\u3092\u3059\u304F\u3081\u308B",
    "\u{1F937}\u{1F3FF}": "\u304A\u624B\u4E0A\u3052\u3059\u308B\u4EBA: \u6FC3\u3044\u808C\u8272 \u304A\u624B\u4E0A\u3052 \u304A\u624B\u4E0A\u3052\u3059\u308B\u4EBA \u3055\u3042\u306D \u30B8\u30A7\u30B9\u30C1\u30E3\u30FC \u308F\u304B\u308A\u307E\u305B\u3093 \u4EBA \u591A\u5206\u306D \u6FC3\u3044\u808C\u8272 \u77E5\u3089\u306A\u3044 \u80A9\u3092\u3059\u304F\u3081\u308B",
    "\u{1F937}\u200D\u2642\uFE0F": "\u304A\u624B\u4E0A\u3052\u3059\u308B\u7537 \u304A\u624B\u4E0A\u3052 \u3055\u3042\u306D \u30B8\u30A7\u30B9\u30C1\u30E3\u30FC \u308F\u304B\u308A\u307E\u305B\u3093 \u591A\u5206\u306D \u7537 \u7537\u6027 \u77E5\u3089\u306A\u3044 \u80A9\u3092\u3059\u304F\u3081\u308B",
