    "\u{1F9D1}\u{1F3FD}\u200D\u{1F37C}": "\u6388\u4E73\u3059\u308B\u4EBA: \u4E2D\u9593\u306E\u808C\u8272 \u4E2D\u9593\u306E\u808C\u8272 \u4EBA \u6388\u4E73 \u6388\u4E73\u3059\u308B\u4EBA \u65B0\u751F\u5150 \u6BCD\u89AA \u7236\u89AA \u8D64\u3061\u3083\u3093",
    "\u{1F9D1}\u{1F3FE}\u200D\u{1F37C}": "\u6388\u4E73\u3059\u308B\u4EBA: \u3084\u3084\u6FC3\u3044\u808C\u8272 \u3084\u3084\u6FC3\u3044\u808C\u8272 \u4EBA \u6388\u4E73 \u6388\u4E73\u3059\u308B\u4EBA \u65B0\u751F\u5150 \u6BCD\u89AA \u7236\u89AA \u8D64\u3061\u3083\u3093",
    "\u{1F9D1}\u{1F3FF}\u200D\u{1F37C}": "\u6388\u4E73\u3059\u308B\u4EBA: \u6FC3\u3044\u808C\u8272 \u4EBA \u6388\u4E73 \u6388\u4E73\u3059\u308B\u4EBA \u65B0\u751F\u5150 \u6BCD\u89AA \u6FC3\u3044\u808C\u8272 \u7236\u89AA \u8D64\u3061\u3083\u3093",
    "\u{1F47C}": "\u5929\u4F7F \u30A8\u30F3\u30B8\u30A7\u30EB \u30A8\u30F3\u30BC\u30EB \u8D64\u3061\u3083\u3093\u5929\u4F7F \u9854",
    "\u{1F47C}\u{1F3FB}": "\u5929\u4F7F: \u8584\u3044\u808C\u8272 \u30A8\u30F3\u30B8\u30A7\u30EB \u30A8\u30F3\u30BC\u30EB \u5929\u4F7F \u8584\u3044\u808C\u8272 \u8D64\u3061\u3083\u3093\u5929\u4F7F \u9854",
    "\u{1F47C}\u{1F3FC}": "\u5929\u4F7F: \u3084\u3084\u8584\u3044\u808C\u8272 \u30A8\u30F3\u30B8\u30A7\u30EB \u30A8\u30F3\u30BC\u30EB \u3084\u3084\u8584\u3044\u808C\u8272 \u5929\u4F7F \u8D64\u3061\u3083\u3093\u5929\u4F7F \u9854",
    "\u{1F47C}\u{1F3FD}": "\u5929\u4F7F: \u4E2D\u9593\u306E\u808C\u8272 \u30A8\u30F3\u30B8\u30A7\u30EB \u30A8\u30F3\u30BC\u30EB \u4E2D\u9593\u306E\u808C\u8272 \u5929\u4F7F \u8D64\u3061\u3083\u3093\u5929\u4F7F \u9854",
    "\u{1F47C}\u{1F3FE}": "\u5929\u4F7F: \u3084\u3084\u6FC3\u3044\u808C\u8272 \u30A8\u30F3\u30B8\u30A7\u30EB \u30A8\u30F3\u30BC\u30EB \u3084\u3084\u6FC3\u3044\u808C\u8272 \u5929\u4F7F \u8D64\u3061\u3083\u3093\u5929\u4F7F \u9854",
    "\u{1F47C}\u{1F3FF}": "\u5929\u4F7F: \u6FC3\u3044\u808C\u8272 \u30A8\u30F3\u30B8\u30A7\u30EB \u30A8\u30F3\u30BC\u30EB \u5929\u4F7F \u6FC3\u3044\u808C\u8272 \u8D64\u3061\u3083\u3093\u5929\u4F7F \u9854",
    "\u{1F385}": "\u30B5\u30F3\u30BF \u30AF\u30EA\u30B9\u30DE\u30B9 \u30B5\u30F3\u30BF\u30AF\u30ED\u30FC\u30B9 \u9854",
    "\u{1F385}\u{1F3FB}": "\u30B5\u30F3\u30BF: \u8584\u3044\u808C\u8272 \u30AF\u30EA\u30B9\u30DE\u30B9 \u30B5\u30F3\u30BF \u30B5\u30F3\u30BF\u30AF\u30ED\u30FC\u30B9 \u8584\u3044\u808C\u8272 \u9854",
    "\u{1F385}\u{1F3FC}": "\u30B5\u30F3\u30BF: \u3084\u3084\u8584\u3044\u808C\u8272 \u30AF\u30EA\u30B9\u30DE\u30B9 \u30B5\u30F3\u30BF \u30B5\u30F3\u30BF\u30AF\u30ED\u30FC\u30B9 \u3084\u3084\u8584\u3044\u808C\u8272 \u9854",
    "\u{1F385}\u{1F3FD}": "\u30B5\u30F3\u30BF: \u4E2D\u9593\u306E\u808C\u8272 \u30AF\u30EA\u30B9\u30DE\u30B9 \u30B5\u30F3\u30BF \u30B5\u30F3\u30BF\u30AF\u30ED\u30FC\u30B9 \u4E2D\u9593\u306E\u808C\u8272 \u9854",
    "\u{1F385}\u{1F3FE}": "\u30B5\u30F3\u30BF: \u3084\u3084\u6FC3\u3044\u808C\u8272 \u30AF\u30EA\u30B9\u30DE\u30B9 \u30B5\u30F3\u30BF \u30B5\u30F3\u30BF\u30AF\u30ED\u30FC\u30B9 \u3084\u3084\u6FC3\u3044\u808C\u8272 \u9854",
    "\u{1F385}\u{1F3FF}": "\u30B5\u30F3\u30BF: \u6FC3\u3044\u808C\u8272 \u30AF\u30EA\u30B9\u30DE\u30B9 \u30B5\u30F3\u30BF \u30B5\u30F3\u30BF\u30AF\u30ED\u30FC\u30B9 \u6FC3\u3044\u808C\u8272 \u9854",
    "\u{1F936}": "\u5973\u6027\u306E\u30B5\u30F3\u30BF \u30AF\u30EA\u30B9\u30DE\u30B9 \u30B5\u30F3\u30BF\u30AF\u30ED\u30FC\u30B9 \u5973 \u5973\u6027",
    "\u{1F936}\u{1F3FB}": "\u5973\u6027\u306E\u30B5\u30F3\u30BF: \u8584\u3044\u808C\u8272 \u30AF\u30EA\u30B9\u30DE\u30B9 \u30B5\u30F3\u30BF\u30AF\u30ED\u30FC\u30B9 \u5973 \u5973\u6027 \u5973\u6027\u306E\u30B5\u30F3\u30BF \u8584\u3044\u808C\u8272",
    "\u{1F936}\u{1F3FC}": "\u5973\u6027\u306E\u30B5\u30F3\u30BF: \u3084\u3084\u8584\u3044\u808C\u8272 \u30AF\u30EA\u30B9\u30DE\u30B9 \u30B5\u30F3\u30BF\u30AF\u30ED\u30FC\u30B9 \u3084\u3084\u8584\u3044\u808C\u8272 \u5973 \u5973\u6027 \u5973\u6027\u306E\u30B5\u30F3\u30BF",
    "\u{1F936}\u{1F3FD}": "\u5973\u6027\u306E\u30B5\u30F3\u30BF: \u4E2D\u9593\u306E\u808C\u8272 \u30AF\u30EA\u30B9\u30DE\u30B9 \u30B5\u30F3\u30BF\u30AF\u30ED\u30FC\u30B9 \u4E2D\u9593\u306E\u808C\u8272 \u5973 \u5973\u6027 \u5973\u6027\u306E\u30B5\u30F3\u30BF",
    "\u{1F936}\u{1F3FE}": "\u5973\u6027\u306E\u30B5\u30F3\u30BF: \u3084\u3084\u6FC3\u3044\u808C\u8272 \u30AF\u30EA\u30B9\u30DE\u30B9 \u30B5\u30F3\u30BF\u30AF\u30ED\u30FC\u30B9 \u3084\u3084\u6FC3\u3044\u808C\u8272 \u5973 \u5973\u6027 \u5973\u6027\u306E\u30B5\u30F3\u30BF",
    "\u{1F936}\u{1F3FF}": "\u5973\u6027\u306E\u30B5\u30F3\u30BF: \u6FC3\u3044\u808C\u8272 \u30AF\u30EA\u30B9\u30DE\u30B9 \u30B5\u30F3\u30BF\u30AF\u30ED\u30FC\u30B9 \u5973 \u5973\u6027 \u5973\u6027\u306E\u30B5\u30F3\u30BF \u6FC3\u3044\u808C\u8272",
    "\u{1F9D1}\u200D\u{1F384}": "\u30B5\u30F3\u30BF\u3055\u3093 \u30AF\u30EA\u30B9\u30DE\u30B9 \u30B5\u30F3\u30BF \u30B5\u30F3\u30BF\u30AF\u30ED\u30FC\u30B9 \u4EBA \u5E3D\u5B50",
    "\u{1F9D1}\u{1F3FB}\u200D\u{1F384}": "\u30B5\u30F3\u30BF\u3055\u3093: \u8584\u3044\u808C\u8272 \u30AF\u30EA\u30B9\u30DE\u30B9 \u30B5\u30F3\u30BF \u30B5\u30F3\u30BF\u30AF\u30ED\u30FC\u30B9 \u30B5\u30F3\u30BF\u3055\u3093 \u4EBA \u5E3D\u5B50 \u8584\u3044\u808C\u8272",
    "\u{1F9D1}\u{1F3FC}\u200D\u{1F384}": "\u30B5\u30F3\u30BF\u3055\u3093: \u3084\u3084\u8584\u3044\u808C\u8272 \u30AF\u30EA\u30B9\u30DE\u30B9 \u30B5\u30F3\u30BF \u30B5\u30F3\u30BF\u30AF\u30ED\u30FC\u30B9 \u30B5\u30F3\u30BF\u3055\u3093 \u3084\u3084\u8584\u3044\u808C\u8272 \u4EBA \u5E3D\u5B50",
    "\u{1F9D1}\u{1F3FD}\u200D\u{1F384}": "\u30B5\u30F3\u30BF\u3055\u3093: \u4E2D\u9593\u306E\u808C\u8272 \u30AF\u30EA\u30B9\u30DE\u30B9 \u30B5\u30F3\u30BF \u30B5\u30F3\u30BF\u30AF\u30ED\u30FC\u30B9 \u30B5\u30F3\u30BF\u3055\u3093 \u4E2D\u9593\u306E\u808C\u8272 \u4EBA \u5E3D\u5B50",
    "\u{1F9D1}\u{1F3FE}\u200D\u{1F384}": "\u30B5\u30F3\u30BF\u3055\u3093: \u3084\u3084\u6FC3\u3044\u808C\u8272 \u30AF\u30EA\u30B9\u30DE\u30B9 \u30B5\u30F3\u30BF \u30B5\u30F3\u30BF\u30AF\u30ED\u30FC\u30B9 \u30B5\u30F3\u30BF\u3055\u3093 \u3084\u3084\u6FC3\u3044\u808C\u8272 \u4EBA \u5E3D\u5B50",
    "\u{1F9D1}\u{1F3FF}\u200D\u{1F384}": "\u30B5\u30F3\u30BF\u3055\u3093: \u6FC3\u3044\u808C\u8272 \u30AF\u30EA\u30B9\u30DE\u30B9 \u30B5\u30F3\u30BF \u30B5\u30F3\u30BF\u30AF\u30ED\u30FC\u30B9 \u30B5\u30F3\u30BF\u3055\u3093 \u4EBA \u5E3D\u5B50 \u6FC3\u3044\u808C\u8272",
    "\u{1F9B8}": "\u30B9\u30FC\u30D1\u30FC\u30D2\u30FC\u30ED\u30FC \u30B9\u30FC\u30D1\u30FC\u30DE\u30F3 \u30D2\u30FC\u30ED\u30FC \u30D2\u30ED\u30A4\u30F3 \u5584 \u5DE8\u5927\u52E2\u529B \u8D85\u4EBA",
