    "\u{1F468}\u{1F3FD}\u200D\u{1F9BD}": "\u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u7537\u6027: \u4E2D\u9593\u306E\u808C\u8272 \u30A2\u30AF\u30BB\u30B7\u30D3\u30EA\u30C6\u30A3 \u4E2D\u9593\u306E\u808C\u8272 \u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u7537\u6027 \u7537\u6027 \u8ECA\u3044\u3059 \u969C\u304C\u3044",
    "\u{1F468}\u{1F3FE}\u200D\u{1F9BD}": "\u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u7537\u6027: \u3084\u3084\u6FC3\u3044\u808C\u8272 \u30A2\u30AF\u30BB\u30B7\u30D3\u30EA\u30C6\u30A3 \u3084\u3084\u6FC3\u3044\u808C\u8272 \u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u7537\u6027 \u7537\u6027 \u8ECA\u3044\u3059 \u969C\u304C\u3044",
    "\u{1F468}\u{1F3FF}\u200D\u{1F9BD}": "\u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u7537\u6027: \u6FC3\u3044\u808C\u8272 \u30A2\u30AF\u30BB\u30B7\u30D3\u30EA\u30C6\u30A3 \u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u7537\u6027 \u6FC3\u3044\u808C\u8272 \u7537\u6027 \u8ECA\u3044\u3059 \u969C\u304C\u3044",
    "\u{1F468}\u200D\u{1F9BD}\u200D\u27A1\uFE0F": "\u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u7537\u6027: \u53F3\u5411\u304D \u30A2\u30AF\u30BB\u30B7\u30D3\u30EA\u30C6\u30A3 \u53F3\u5411\u304D \u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u7537\u6027 \u7537\u6027 \u8ECA\u3044\u3059 \u969C\u304C\u3044",
    "\u{1F468}\u{1F3FB}\u200D\u{1F9BD}\u200D\u27A1\uFE0F": "\u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u7537\u6027: \u8584\u3044\u808C\u8272 \u53F3\u5411\u304D \u30A2\u30AF\u30BB\u30B7\u30D3\u30EA\u30C6\u30A3 \u53F3\u5411\u304D \u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u7537\u6027 \u7537\u6027 \u8584\u3044\u808C\u8272 \u8ECA\u3044\u3059 \u969C\u304C\u3044",
    "\u{1F468}\u{1F3FC}\u200D\u{1F9BD}\u200D\u27A1\uFE0F": "\u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u7537\u6027: \u3084\u3084\u8584\u3044\u808C\u8272 \u53F3\u5411\u304D \u30A2\u30AF\u30BB\u30B7\u30D3\u30EA\u30C6\u30A3 \u3084\u3084\u8584\u3044\u808C\u8272 \u53F3\u5411\u304D \u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u7537\u6027 \u7537\u6027 \u8ECA\u3044\u3059 \u969C\u304C\u3044",
    "\u{1F468}\u{1F3FD}\u200D\u{1F9BD}\u200D\u27A1\uFE0F": "\u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u7537\u6027: \u4E2D\u9593\u306E\u808C\u8272 \u53F3\u5411\u304D \u30A2\u30AF\u30BB\u30B7\u30D3\u30EA\u30C6\u30A3 \u4E2D\u9593\u306E\u808C\u8272 \u53F3\u5411\u304D \u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u7537\u6027 \u7537\u6027 \u8ECA\u3044\u3059 \u969C\u304C\u3044",
    "\u{1F468}\u{1F3FE}\u200D\u{1F9BD}\u200D\u27A1\uFE0F": "\u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u7537\u6027: \u3084\u3084\u6FC3\u3044\u808C\u8272 \u53F3\u5411\u304D \u30A2\u30AF\u30BB\u30B7\u30D3\u30EA\u30C6\u30A3 \u3084\u3084\u6FC3\u3044\u808C\u8272 \u53F3\u5411\u304D \u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u7537\u6027 \u7537\u6027 \u8ECA\u3044\u3059 \u969C\u304C\u3044",
    "\u{1F468}\u{1F3FF}\u200D\u{1F9BD}\u200D\u27A1\uFE0F": "\u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u7537\u6027: \u6FC3\u3044\u808C\u8272 \u53F3\u5411\u304D \u30A2\u30AF\u30BB\u30B7\u30D3\u30EA\u30C6\u30A3 \u53F3\u5411\u304D \u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u7537\u6027 \u6FC3\u3044\u808C\u8272 \u7537\u6027 \u8ECA\u3044\u3059 \u969C\u304C\u3044",
    "\u{1F469}\u200D\u{1F9BD}": "\u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u5973\u6027 \u30A2\u30AF\u30BB\u30B7\u30D3\u30EA\u30C6\u30A3 \u5973\u6027 \u8ECA\u3044\u3059 \u969C\u304C\u3044",
    "\u{1F469}\u{1F3FB}\u200D\u{1F9BD}": "\u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u5973\u6027: \u8584\u3044\u808C\u8272 \u30A2\u30AF\u30BB\u30B7\u30D3\u30EA\u30C6\u30A3 \u5973\u6027 \u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u5973\u6027 \u8584\u3044\u808C\u8272 \u8ECA\u3044\u3059 \u969C\u304C\u3044",
    "\u{1F469}\u{1F3FC}\u200D\u{1F9BD}": "\u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u5973\u6027: \u3084\u3084\u8584\u3044\u808C\u8272 \u30A2\u30AF\u30BB\u30B7\u30D3\u30EA\u30C6\u30A3 \u3084\u3084\u8584\u3044\u808C\u8272 \u5973\u6027 \u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u5973\u6027 \u8ECA\u3044\u3059 \u969C\u304C\u3044",
    "\u{1F469}\u{1F3FD}\u200D\u{1F9BD}": "\u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u5973\u6027: \u4E2D\u9593\u306E\u808C\u8272 \u30A2\u30AF\u30BB\u30B7\u30D3\u30EA\u30C6\u30A3 \u4E2D\u9593\u306E\u808C\u8272 \u5973\u6027 \u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u5973\u6027 \u8ECA\u3044\u3059 \u969C\u304C\u3044",
    "\u{1F469}\u{1F3FE}\u200D\u{1F9BD}": "\u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u5973\u6027: \u3084\u3084\u6FC3\u3044\u808C\u8272 \u30A2\u30AF\u30BB\u30B7\u30D3\u30EA\u30C6\u30A3 \u3084\u3084\u6FC3\u3044\u808C\u8272 \u5973\u6027 \u624B\u52D5\u5F0F\u8ECA\u6905\u5B50\u306E\u5973\u6027 \u8ECA\u3044\u3059 \u969C\u304C\u3044",
