    "\u{1F9A9}": "\u30D5\u30E9\u30DF\u30F3\u30B4 \u30D4\u30F3\u30AF\u8272 \u52D5\u7269 \u6D3E\u624B \u71B1\u5E2F \u9CE5",
    "\u{1F99A}": "\u30AF\u30B8\u30E3\u30AF \u30D4\u30FC\u30B3\u30C3\u30AF \u5B54\u96C0 \u6D3E\u624B \u9CE5",
    "\u{1F99C}": "\u30AA\u30A6\u30E0 \u3057\u3083\u3079\u308B \u52D5\u7269 \u6D77\u8CCA \u9CE5",
    "\u{1FABD}": "\u7FFC \u5929\u4F7F \u5929\u56FD \u795E\u8A71 \u7A7A \u7FBD \u98DB\u3073\u7ACB\u3064 \u98DB\u3076 \u98DB\u884C \u9CE5",
    "\u{1F426}\u200D\u2B1B": "\u9ED2\u3044\u9CE5 \u30AB\u30FC\u30AB\u30FC \u30AB\u30E9\u30B9 \u304F\u3061\u3070\u3057 \u30B3\u30AF\u30C1\u30E7\u30A6 \u30DF\u30E4\u30DE\u30AC\u30E9\u30B9 \u30EF\u30BF\u30EA\u30AC\u30E9\u30B9 \u70CF \u9CE5 \u9CE5\u985E \u9ED2",
    "\u{1FABF}": "\u30AC\u30C1\u30E7\u30A6 \u30A2\u30D2\u30EB \u30AC\u30FC\u30AC\u30FC \u307E\u306C\u3051 \u9CE5 \u9CE5\u985E",
    "\u{1F426}\u200D\u{1F525}": "\u30D5\u30A7\u30CB\u30C3\u30AF\u30B9 \u30D5\u30A1\u30F3\u30BF\u30B8\u30FC \u4E0D\u6B7B\u9CE5 \u518D\u751F \u5FA9\u6D3B \u706B\u306E\u9CE5 \u751F\u307E\u308C\u5909\u308F\u308A \u795E\u8A71 \u8EE2\u751F \u8F2A\u5EFB",
    "\u{1F438}": "\u30AB\u30A8\u30EB\u306E\u9854 \u30AB\u30A8\u30EB \u52D5\u7269 \u9854",
    "\u{1F40A}": "\u30EF\u30CB \u30AF\u30ED\u30B3\u30C0\u30A4\u30EB \u52D5\u7269 \u722C\u866B\u985E",
    "\u{1F422}": "\u30AB\u30E1 \u4E80 \u52D5\u7269 \u722C\u866B\u985E",
    "\u{1F98E}": "\u30C8\u30AB\u30B2 \u30E4\u30E2\u30EA \u52D5\u7269 \u722C\u866B\u985E",
    "\u{1F40D}": "\u30D8\u30D3 \u3078\u3073\u3064\u304B\u3044\u5EA7 \u52D5\u7269 \u661F\u5EA7 \u6BD2 \u722C\u866B\u985E",
    "\u{1F432}": "\u30C9\u30E9\u30B4\u30F3\u306E\u9854 \u30C9\u30E9\u30B4\u30F3 \u52D5\u7269 \u7ADC \u9854 \u9F8D",
    "\u{1F409}": "\u30C9\u30E9\u30B4\u30F3 \u52D5\u7269 \u7ADC \u9F8D",
    "\u{1F995}": "\u8349\u98DF\u6050\u7ADC \u30C7\u30A3\u30D7\u30ED\u30C9\u30AF\u30B9 \u30D6\u30E9\u30AD\u30AA\u30B5\u30A6\u30EB\u30B9 \u30D6\u30ED\u30F3\u30C8\u30B5\u30A6\u30EB\u30B9 \u6050\u7ADC \u7ADC\u811A\u985E",
    "\u{1F996}": "\u30C6\u30A3\u30E9\u30CE\u30B5\u30A6\u30EB\u30B9 \u6050\u7ADC",
    "\u{1F433}": "\u6F6E\u5439\u304D\u30AF\u30B8\u30E9 \u30AF\u30B8\u30E9 \u52D5\u7269 \u6F6E\u5439\u304D",
    "\u{1F40B}": "\u30AF\u30B8\u30E9 \u52D5\u7269",
    "\u{1F42C}": "\u30A4\u30EB\u30AB \u30C9\u30EB\u30D5\u30A3\u30F3 \u52D5\u7269",
    "\u{1FACD}": "\u30B7\u30E3\u30C1 \u30AF\u30B8\u30E9 \u6D77 \u6D77\u6D0B",
    "\u{1F9AD}": "\u30A2\u30B6\u30E9\u30B7 \u30A2\u30B7\u30AB \u30AA\u30C3\u30C8\u30BB\u30A4 \u30C8\u30C9 \u52D5\u7269 \u6D77\u7363",
    "\u{1F41F}": "\u9B5A \u3046\u304A\u5EA7 \u30D5\u30A3\u30C3\u30B7\u30F3\u30B0 \u52D5\u7269 \u661F\u5EA7 \u91E3\u308A",
    "\u{1F420}": "\u71B1\u5E2F\u9B5A \u52D5\u7269 \u9B5A",
    "\u{1F421}": "\u30D5\u30B0 \u52D5\u7269 \u9B5A",
    "\u{1F988}": "\u30B5\u30E1 \u52D5\u7269 \u9B5A",
    "\u{1F419}": "\u30BF\u30B3 \u30AA\u30AF\u30C8\u30D1\u30B9 \u52D5\u7269 \u8EDF\u4F53\u52D5\u7269",
    "\u{1F41A}": "\u5DFB\u304D\u8C9D \u52D5\u7269 \u8C9D \u8C9D\u6BBB",
    "\u{1FAB8}": "\u30B5\u30F3\u30B4 \u6C17\u5019\u5909\u52D5 \u6D77 \u73CA\u745A\u7901",
    "\u{1FABC}": "\u30AF\u30E9\u30B2 \u30D7\u30E9\u30F3\u30AF\u30C8\u30F3 \u523A\u3059 \u6BD2 \u6C34\u65CF\u9928 \u6D77 \u6D77\u6D0B\u751F\u7269 \u7121\u810A\u690E\u52D5\u7269 \u89E6\u624B \u91DD",
