    "\u{1F99E}": "\u30B6\u30EA\u30AC\u30CB \u30B7\u30FC\u30D5\u30FC\u30C9 \u306F\u3055\u307F \u30D3\u30B9\u30AF \u30EC\u30C3\u30C9\u30ED\u30D6\u30B9\u30BF\u30FC \u30ED\u30D6\u30B9\u30BF\u30FC \u52D5\u7269",
    "\u{1F990}": "\u30A8\u30D3 \u30B7\u30FC\u30D5\u30FC\u30C9 \u30B7\u30E5\u30EA\u30F3\u30D7 \u52D5\u7269 \u5C0F\u30A8\u30D3",
    "\u{1F991}": "\u30A4\u30AB \u30B7\u30FC\u30D5\u30FC\u30C9 \u52D5\u7269 \u8EDF\u4F53\u52D5\u7269",
