    "\u{1F40C}": "\u304B\u305F\u3064\u3080\u308A \u30A8\u30B9\u30AB\u30EB\u30B4 \u30AB\u30BF\u30C4\u30E0\u30EA \u3067\u3093\u3067\u3093\u866B \u866B",
    "\u{1F98B}": "\u30C1\u30E7\u30A6 \u30D0\u30BF\u30D5\u30E9\u30A4 \u6606\u866B \u866B \u8776",
