    "\u{1F41C}": "\u30A2\u30EA \u6606\u866B \u866B",
    "\u{1F41D}": "\u30DF\u30C4\u30D0\u30C1 \u30CF\u30C1 \u866B \u8702",
    "\u{1FAB2}": "\u30AB\u30D6\u30C8\u30E0\u30B7 \u3064\u306E \u6606\u866B \u866B",
    "\u{1F41E}": "\u30C6\u30F3\u30C8\u30A6\u30E0\u30B7 \u3066\u3093\u3068\u3046\u866B \u866B",
    "\u{1F997}": "\u30D0\u30C3\u30BF \u30B3\u30AA\u30ED\u30AE \u6606\u866B \u76F4\u7FC5\u76EE \u866B",
