    "\u{1F577}\uFE0F": "\u30AF\u30E2 \u30B9\u30D1\u30A4\u30C0\u30FC \u866B",
    "\u{1F578}\uFE0F": "\u30AF\u30E2\u306E\u5DE3 \u30A6\u30A7\u30D6 \u30AF\u30E2 \u30B9\u30D1\u30A4\u30C0\u30FC",
    "\u{1F982}": "\u30B5\u30BD\u30EA \u3055\u305D\u308A\u5EA7 \u661F\u5EA7 \u866B",
    "\u{1F99F}": "\u868A \u30A6\u30A4\u30EB\u30B9 \u30DE\u30E9\u30EA\u30A2 \u523A\u3059 \u71B1 \u75C5\u6C17 \u866B",
    "\u{1FAB0}": "\u30CF\u30A8 \u4E0D\u6F54 \u5BB3\u866B \u75C5\u539F\u83CC \u866B",
    "\u{1FAB1}": "\u30DF\u30DF\u30BA \u5BC4\u751F\u866B \u866B",
    "\u{1F9A0}": "\u5FAE\u751F\u7269 \u30A2\u30E1\u30FC\u30D0 \u30A6\u30A4\u30EB\u30B9 \u30D0\u30AF\u30C6\u30EA\u30A2 \u79D1\u5B66 \u7D30\u83CC",
    "\u{1F490}": "\u82B1\u675F \u30D6\u30FC\u30B1 \u690D\u7269 \u82B1",
    "\u{1F338}": "\u685C \u30B5\u30AF\u30E9 \u690D\u7269 \u82B1 \u958B\u82B1",
    "\u{1F4AE}": "\u5927\u5909\u3088\u304F\u3067\u304D\u307E\u3057\u305F \u306F\u306A\u307E\u308B \u3088\u304F\u3067\u304D\u307E\u3057\u305F \u82B1",
    "\u{1FAB7}": "\u30CF\u30B9\u306E\u82B1 \u30D2\u30F3\u30C9\u30A5\u30FC\u6559 \u4ECF\u6559 \u6975\u697D \u6E05\u6D44 \u82B1",
    "\u{1F3F5}\uFE0F": "\u82B1\u98FE\u308A \u690D\u7269 \u82B1",
    "\u{1F339}": "\u30D0\u30E9 \u30ED\u30FC\u30BA \u690D\u7269 \u82B1 \u8594\u8587 \u8D64\u3044\u30D0\u30E9",
    "\u{1F940}": "\u3057\u304A\u308C\u305F\u82B1 \u3057\u304A\u308C\u305F \u82B1",
    "\u{1F33A}": "\u30CF\u30A4\u30D3\u30B9\u30AB\u30B9 \u690D\u7269 \u82B1",
    "\u{1F33B}": "\u30D2\u30DE\u30EF\u30EA \u3072\u307E\u308F\u308A \u82B1",
    "\u{1F33C}": "\u958B\u82B1 \u30AD\u30F3\u30DD\u30A6\u30B2 \u54B2\u3044\u305F\u82B1 \u690D\u7269 \u82B1",
    "\u{1F337}": "\u30C1\u30E5\u30FC\u30EA\u30C3\u30D7 \u690D\u7269 \u82B1 \u958B\u82B1",
    "\u{1FABB}": "\u30D2\u30E4\u30B7\u30F3\u30B9 \u30B9\u30DF\u30EC\u8272 \u30D6\u30EB\u30FC\u30DC\u30CD\u30C3\u30C8 \u30E9\u30A4\u30E9\u30C3\u30AF \u30E9\u30D9\u30F3\u30C0\u30FC \u690D\u7269 \u7D2B\u8272 \u82B1 \u9752\u7D2B",
    "\u{1F331}": "\u65B0\u82BD \u53CC\u8449 \u82BD",
    "\u{1FAB4}": "\u9262\u690D\u3048 \u30D9\u30E9\u30F3\u30C0 \u690D\u6728\u9262 \u690D\u7269 \u6C34\u3084\u308A \u7DD1 \u82D7 \u89B3\u8449\u690D\u7269",
