    "\u{1F333}": "\u843D\u8449\u6A39 \u6728 \u68EE",
    "\u{1F334}": "\u30E4\u30B7\u306E\u6728 \u30D3\u30FC\u30C1 \u30E4\u30B7 \u6728 \u71B1\u5E2F",
