    "\u2618\uFE0F": "\u30AF\u30ED\u30FC\u30D0\u30FC \u690D\u7269 \u8349 \u8449",
    "\u{1F340}": "\u56DB\u3064\u8449\u306E\u30AF\u30ED\u30FC\u30D0\u30FC 4 \u30AF\u30ED\u30FC\u30D0\u30FC \u690D\u7269 \u8349 \u8449",
    "\u{1F341}": "\u304B\u3048\u3067 \u30AB\u30A8\u30C7 \u3082\u307F\u3058 \u7D05\u8449 \u843D\u3061\u8449 \u8449",
    "\u{1F342}": "\u843D\u3061\u8449 \u6728\u306E\u8449 \u67AF\u308C\u8449 \u8449 \u8449\u3063\u3071",
    "\u{1F343}": "\u98A8\u306B\u63FA\u308C\u308B\u8449 \u6728\u306E\u8449 \u843D\u3061\u8449 \u8449 \u8449\u3063\u3071 \u98A8",
    "\u{1FAB9}": "\u7A7A\u3063\u307D\u306E\u5DE3 \u55B6\u5DE3 \u5DE3 \u5DE3\u4F5C\u308A",
