    "\u{1F344}": "\u30AD\u30CE\u30B3 \u304D\u306E\u3053 \u30DE\u30C3\u30B7\u30E5\u30EB\u30FC\u30E0 \u6BD2 \u83CC\u985E \u91CE\u83DC",
    "\u{1FABE}": "\u67AF\u308C\u6728 \u4E0D\u6BDB \u51AC \u5E72\u3070\u3064 \u8449\u306E\u306A\u3044\u6728",
    "\u{1F347}": "\u3076\u3069\u3046 \u30B0\u30EC\u30FC\u30D7 \u30D6\u30C9\u30A6 \u679C\u7269",
