    "\u{1F34B}": "\u30EC\u30E2\u30F3 \u679C\u7269 \u67D1\u6A58\u985E \u9178\u3063\u3071\u3044",
    "\u{1F34B}\u200D\u{1F7E9}": "\u30E9\u30A4\u30E0 \u3055\u308F\u3084\u304B \u30C8\u30ED\u30D4\u30AB\u30EB \u30D5\u30EB\u30FC\u30C4 \u30DE\u30EB\u30AC\u30EA\u30FC\u30BF \u30E2\u30D2\u30FC\u30C8 \u679C\u7269 \u67D1\u6A58\u985E \u7DD1 \u9178\u3063\u3071\u3044",
    "\u{1F34C}": "\u30D0\u30CA\u30CA \u30AB\u30EA\u30A6\u30E0 \u679C\u7269",
    "\u{1F34D}": "\u30D1\u30A4\u30CA\u30C3\u30D7\u30EB \u30C8\u30ED\u30D4\u30AB\u30EB \u30D1\u30A4\u30F3 \u679C\u7269",
    "\u{1F96D}": "\u30DE\u30F3\u30B4\u30FC \u30C8\u30ED\u30D4\u30AB\u30EB \u30D5\u30EB\u30FC\u30C4 \u679C\u7269 \u98DF\u3079\u7269",
    "\u{1F34E}": "\u8D64\u30EA\u30F3\u30B4 \u30A2\u30C3\u30D7\u30EB \u308A\u3093\u3054 \u679C\u7269",
    "\u{1F34F}": "\u9752\u30EA\u30F3\u30B4 \u30A2\u30C3\u30D7\u30EB \u308A\u3093\u3054 \u679C\u7269",
    "\u{1F350}": "\u6D0B\u30CA\u30B7 \u30CA\u30B7 \u679C\u7269 \u897F\u6D0B\u30CA\u30B7",
    "\u{1F351}": "\u6843 \u30D4\u30FC\u30C1 \u679C\u7269",
    "\u{1F352}": "\u3055\u304F\u3089\u3093\u307C \u30C1\u30A7\u30EA\u30FC \u679C\u7269",
