    "\u{1F951}": "\u30A2\u30DC\u30AB\u30C9 \u679C\u7269 \u91CE\u83DC",
    "\u{1F346}": "\u30CA\u30B9 \u91CE\u83DC",
    "\u{1F954}": "\u30B8\u30E3\u30AC\u30A4\u30E2 \u30A4\u30E2 \u3058\u3083\u304C\u3044\u3082 \u30DD\u30C6\u30C8 \u91CE\u83DC",
    "\u{1F955}": "\u4EBA\u53C2 \u30CB\u30F3\u30B8\u30F3 \u91CE\u83DC",
    "\u{1F33D}": "\u3068\u3046\u3082\u308D\u3053\u3057 \u30B3\u30FC\u30F3 \u30C8\u30A6\u30E2\u30ED\u30B3\u30B7 \u91CE\u83DC",
    "\u{1F336}\uFE0F": "\u3068\u3046\u304C\u3089\u3057 \u8F9B\u3044 \u91CE\u83DC \u9999\u8F9B\u6599",
    "\u{1FAD1}": "\u30D4\u30FC\u30DE\u30F3 \u3068\u3046\u304C\u3089\u3057 \u30D1\u30D7\u30EA\u30AB \u91CE\u83DC \u9752\u30D4\u30FC\u30DE\u30F3",
    "\u{1F952}": "\u30AD\u30E5\u30A6\u30EA \u30D4\u30AF\u30EB\u30B9 \u6F2C\u3051\u7269 \u91CE\u83DC",
