    "\u{1FA89}": "\u30CF\u30FC\u30D7 \u30AA\u30FC\u30B1\u30B9\u30C8\u30E9 \u30AD\u30E5\u30FC\u30D4\u30C3\u30C9 \u5F26\u697D\u5668 \u611B \u697D\u5668 \u97F3\u697D",
    "\u{1F4F1}": "\u643A\u5E2F\u96FB\u8A71 \u30B9\u30DE\u30FC\u30C8\u30D5\u30A9\u30F3 \u30B9\u30DE\u30DB \u30E2\u30D0\u30A4\u30EB \u643A\u5E2F",
    "\u{1F4F2}": "\u7740\u4FE1\u4E2D \u30B9\u30DE\u30FC\u30C8\u30D5\u30A9\u30F3 \u30B9\u30DE\u30DB \u30E2\u30D0\u30A4\u30EB \u53D7\u4FE1 \u643A\u5E2F\u53D7\u4FE1 \u643A\u5E2F\u96FB\u8A71 \u96FB\u8A71",
    "\u260E\uFE0F": "\u56FA\u5B9A\u96FB\u8A71 \u30DC\u30BF\u30F3\u5F0F\u96FB\u8A71 \u89AA\u6A5F \u96FB\u8A71 \u9ED2\u96FB\u8A71",
    "\u{1F4DE}": "\u53D7\u8A71\u5668 \u5B50\u6A5F \u96FB\u8A71",
    "\u{1F4DF}": "\u30DD\u30B1\u30D9\u30EB \u30DA\u30FC\u30B8\u30E3\u30FC \u30DD\u30B1\u30C3\u30C8\u30D9\u30EB",
    "\u{1F4E0}": "\u30D5\u30A1\u30C3\u30AF\u30B9 FAX \u8907\u5408\u6A5F \u96FB\u8A71",
    "\u{1F50B}": "\u96FB\u6C60 \u30D0\u30C3\u30C6\u30EA\u30FC \u4E7E\u96FB\u6C60",
