    "\u{1F50C}": "\u30B3\u30F3\u30BB\u30F3\u30C8 \u30D7\u30E9\u30B0 \u96FB\u6C17 \u96FB\u6E90",
    "\u{1F4BB}": "\u30CE\u30FC\u30C8\u30D1\u30BD\u30B3\u30F3 PC \u30B3\u30F3\u30D4\u30E5\u30FC\u30BF\u30FC \u30D1\u30BD\u30B3\u30F3 \u30E9\u30C3\u30D7\u30C8\u30C3\u30D7",
    "\u{1F5A5}\uFE0F": "\u30C7\u30B9\u30AF\u30C8\u30C3\u30D7\u30D1\u30BD\u30B3\u30F3 PC \u30B3\u30F3\u30D4\u30E5\u30FC\u30BF\u30FC \u30C7\u30B9\u30AF\u30C8\u30C3\u30D7 \u30D1\u30BD\u30B3\u30F3 \u30E2\u30CB\u30BF\u30FC",
    "\u{1F5A8}\uFE0F": "\u30D7\u30EA\u30F3\u30BF \u30B3\u30D4\u30FC\u6A5F \u30B3\u30F3\u30D4\u30E5\u30FC\u30BF\u30FC \u30D7\u30EA\u30F3\u30BF\u30FC \u5370\u5237\u6A5F \u8907\u5408\u6A5F",
    "\u2328\uFE0F": "\u30AD\u30FC\u30DC\u30FC\u30C9 PC \u30B3\u30F3\u30D4\u30E5\u30FC\u30BF\u30FC \u30D1\u30BD\u30B3\u30F3",
    "\u{1F5B1}\uFE0F": "\u30DE\u30A6\u30B9 PC \u30B3\u30F3\u30D4\u30E5\u30FC\u30BF\u30FC \u30D1\u30BD\u30B3\u30F3",
    "\u{1F5B2}\uFE0F": "\u30C8\u30E9\u30C3\u30AF\u30DC\u30FC\u30EB PC \u30B3\u30F3\u30D4\u30E5\u30FC\u30BF\u30FC \u30D1\u30BD\u30B3\u30F3",
    "\u{1F4BD}": "MD MO \u30B3\u30F3\u30D4\u30E5\u30FC\u30BF\u30FC \u30DF\u30CB\u30C7\u30A3\u30B9\u30AF",
    "\u{1F4BE}": "\u30D5\u30ED\u30C3\u30D4\u30FC FD \u30B3\u30F3\u30D4\u30E5\u30FC\u30BF\u30FC \u30C7\u30A3\u30B9\u30AF \u30D5\u30ED\u30C3\u30D4\u30FC\u30C7\u30A3\u30B9\u30AF",
    "\u{1F4BF}": "CD Blu-ray DVD \u30B3\u30F3\u30D4\u30E5\u30FC\u30BF\u30FC \u30C7\u30A3\u30B9\u30AF \u30D6\u30EB\u30FC\u30EC\u30A4 \u5149\u30C7\u30A3\u30B9\u30AF",
    "\u{1F4C0}": "DVD Blu-ray CD \u30C7\u30A3\u30B9\u30AF \u30D6\u30EB\u30FC\u30EC\u30A4",
    "\u{1F9EE}": "\u305D\u308D\u3070\u3093 \u30A2\u30D0\u30AB\u30B9 \u7B97\u76E4 \u8A08\u7B97",
    "\u{1F3A5}": "\u6620\u753B\u30AB\u30E1\u30E9 \u30AB\u30E1\u30E9 \u30B7\u30CD\u30DE \u30CF\u30EA\u30A6\u30C3\u30C9 \u30D5\u30A3\u30EB\u30E0 \u30E0\u30FC\u30D3\u30FC \u64AE\u5F71 \u6620\u753B",
    "\u{1F39E}\uFE0F": "\u6620\u753B\u30D5\u30A3\u30EB\u30E0 \u30B7\u30CD\u30DE \u30D5\u30A3\u30EB\u30E0 \u30D5\u30EC\u30FC\u30E0 \u30E0\u30FC\u30D3\u30FC \u6620\u753B",
    "\u{1F4FD}\uFE0F": "\u6620\u5199\u6A5F \u30D3\u30C7\u30AA \u30D5\u30A3\u30EB\u30E0 \u30D7\u30ED\u30B8\u30A7\u30AF\u30BF\u30FC \u30E0\u30FC\u30D3\u30FC \u6620\u753B",
    "\u{1F3AC}": "\u30AB\u30C1\u30F3\u30B3 \u6620\u753B",
    "\u{1F4FA}": "\u30C6\u30EC\u30D3 TV \u30D3\u30C7\u30AA",
    "\u{1F4F7}": "\u30AB\u30E1\u30E9 \u5199\u771F",
    "\u{1F4F8}": "\u30D5\u30E9\u30C3\u30B7\u30E5\u3092\u711A\u3044\u3066\u3044\u308B\u30AB\u30E1\u30E9 \u30AB\u30E1\u30E9 \u30AB\u30E1\u30E9\u30D5\u30E9\u30C3\u30B7\u30E5 \u30D5\u30E9\u30C3\u30B7\u30E5 \u5199\u771F",
    "\u{1F4F9}": "\u30D3\u30C7\u30AA\u30AB\u30E1\u30E9 \u30AB\u30E1\u30E9 \u30D3\u30C7\u30AA \u30E0\u30FC\u30D3\u30FC \u52D5\u753B \u9332\u753B",
    "\u{1F4FC}": "\u30D3\u30C7\u30AA\u30C6\u30FC\u30D7 VHS \u30C6\u30FC\u30D7 \u30D3\u30C7\u30AA \u30D3\u30C7\u30AA\u30AB\u30BB\u30C3\u30C8 \u52D5\u753B",
    "\u{1F50D}": "\u866B\u773C\u93E1\u5DE6 \u30EB\u30FC\u30DA \u62E1\u5927\u93E1 \u691C\u7D22 \u79D1\u5B66 \u866B\u3081\u304C\u306D",
    "\u{1F50E}": "\u866B\u773C\u93E1\u53F3 \u30EB\u30FC\u30DA \u62E1\u5927\u93E1 \u691C\u7D22 \u79D1\u5B66 \u866B\u3081\u304C\u306D",
    "\u{1F56F}\uFE0F": "\u308D\u3046\u305D\u304F \u30AD\u30E3\u30F3\u30C9\u30EB \u30ED\u30A6\u30BD\u30AF \u660E\u304B\u308A",
    "\u{1F4A1}": "\u96FB\u7403 \u3074\u3053\u30FC\u3093 \u3072\u3089\u3081\u304D \u30DE\u30F3\u30AC \u660E\u304B\u308A",
    "\u{1F526}": "\u61D0\u4E2D\u96FB\u706F \u30E9\u30A4\u30C8 \u660E\u304B\u308A",
    "\u{1F3EE}": "\u8D64\u3061\u3087\u3046\u3061\u3093 \u3061\u3087\u3046\u3061\u3093 \u5C45\u9152\u5C4B \u98F2\u307F\u5C4B",
    "\u{1FA94}": "\u30C7\u30A3\u30E4\u30E9\u30F3\u30D7 \u30AA\u30A4\u30EB \u30E9\u30F3\u30D7 \u660E\u304B\u308A",
    "\u{1F4D4}": "\u8868\u7D19\u4ED8\u304D\u30CE\u30FC\u30C8 \u30CE\u30FC\u30C8 \u5B66\u6821 \u6587\u5177 \u6587\u623F\u5177 \u672C",
    "\u{1F4D5}": "\u9589\u3058\u305F\u672C \u66F8\u7C4D \u672C \u8D64\u3044\u672C",
    "\u{1F4D6}": "\u958B\u3044\u305F\u672C \u56F3\u66F8\u9928 \u5C0F\u8AAC \u66F8\u7C4D \u672C \u77E5\u8B58 \u8AAD\u66F8",
    "\u{1F4D7}": "\u7DD1\u306E\u672C \u56F3\u66F8\u9928 \u66F8\u7C4D \u672C \u8AAD\u66F8",
    "\u{1F4D8}": "\u9752\u306E\u672C \u56F3\u66F8\u9928 \u66F8\u7C4D \u672C \u8AAD\u66F8 \u9752\u3044\u672C",
    "\u{1F4D9}": "\u30AA\u30EC\u30F3\u30B8\u306E\u672C \u56F3\u66F8\u9928 \u66F8\u7C4D \u672C \u8AAD\u66F8",
    "\u{1F4DA}": "\u672C\u306E\u5C71 \u52C9\u5F37 \u5B66\u6821 \u5C0F\u8AAC \u66F8\u7C4D \u672C \u8AAD\u66F8",
    "\u{1F4D3}": "\u30CE\u30FC\u30C8 \u624B\u5E33 \u6587\u5177 \u6587\u623F\u5177",
    "\u{1F4D2}": "\u30EA\u30F3\u30B0\u30CE\u30FC\u30C8 \u30CE\u30FC\u30C8 \u53F0\u5E33 \u6587\u5177 \u6587\u623F\u5177",
    "\u{1F4C3}": "\u5DFB\u304D\u30DA\u30FC\u30B8 \u30AB\u30FC\u30EB \u30C9\u30AD\u30E5\u30E1\u30F3\u30C8 \u6587\u66F8 \u66F8\u985E",
    "\u{1F4DC}": "\u5DFB\u304D\u7269 \u6587\u66F8 \u66F8\u985E \u7D19",
    "\u{1F4C4}": "\u30DA\u30FC\u30B8 \u30C9\u30AD\u30E5\u30E1\u30F3\u30C8 \u6587\u66F8 \u66F8\u985E",
    "\u{1F4F0}": "\u65B0\u805E \u30CB\u30E5\u30FC\u30B9 \u65B0\u805E\u7D19",
    "\u{1F5DE}\uFE0F": "\u4E38\u3081\u305F\u65B0\u805E \u30CB\u30E5\u30FC\u30B9 \u65B0\u805E \u65B0\u805E\u7D19",
    "\u{1F4D1}": "\u30DA\u30FC\u30B8\u306B\u4ED8\u7B8B \u3075\u305B\u3093 \u4ED8\u7B8B \u6587\u5177 \u6587\u623F\u5177",
    "\u{1F516}": "\u3057\u304A\u308A \u30BF\u30B0 \u30D6\u30C3\u30AF\u30DE\u30FC\u30AF \u4ED8\u7B8B",
    "\u{1F3F7}\uFE0F": "\u8377\u672D \u30BF\u30B0 \u30E9\u30D9\u30EB",
    "\u{1FA99}": "\u30B3\u30A4\u30F3 \u304A\u91D1 \u5C0F\u92AD \u786C\u8CA8 \u91D1\u8CA8 \u9280\u8CA8",
    "\u{1F4B0}": "\u30C9\u30EB\u888B \u304A\u91D1 \u30AD\u30E3\u30C3\u30B7\u30E5 \u30C9\u30EB \u73FE\u91D1 \u8CDE\u91D1 \u8CED\u3051\u91D1 \u91D1\u6301\u3061 \u91D1\u888B \u9280\u884C",
    "\u{1FA8E}": "\u5B9D\u7BB1 \u304A\u5B9D \u304A\u91D1 \u30B8\u30E5\u30A8\u30EA\u30FC \u5B9D\u77F3 \u5BCC \u8CA1\u5B9D \u8CB4\u91D1\u5C5E \u91D1\u8CA8",
    "\u{1F4B4}": "\u5186\u672D \u304A\u672D \u304A\u91D1 \u5186 \u672D\u675F \u7D19\u5E63 \u901A\u8CA8",
    "\u{1F4B5}": "\u30C9\u30EB\u672D \u304A\u672D \u304A\u91D1 \u30C9\u30EB \u672D\u675F \u7D19\u5E63 \u901A\u8CA8",
    "\u{1F4B6}": "\u30E6\u30FC\u30ED\u672D \u304A\u672D \u304A\u91D1 \u30E6\u30FC\u30ED \u672D\u675F \u7D19\u5E63 \u901A\u8CA8",
