    "\u{1F4B8}": "\u7FBD\u304C\u751F\u3048\u305F\u304A\u91D1 \u304A\u672D \u304A\u91D1 \u30C9\u30EB \u652F\u6255\u3044 \u672D\u675F \u7D19\u5E63",
    "\u{1F4B3}": "\u30AF\u30EC\u30B8\u30C3\u30C8\u30AB\u30FC\u30C9 \u304A\u91D1 \u30AB\u30FC\u30C9 \u30AD\u30E3\u30C3\u30B7\u30E5\u30AB\u30FC\u30C9 \u652F\u6255\u3044 \u9280\u884C",
    "\u{1F9FE}": "\u30EC\u30B7\u30FC\u30C8 \u4F1A\u8A08 \u7C3F\u8A18 \u8ACB\u6C42\u66F8 \u9818\u53CE\u66F8",
    "\u{1F4B9}": "\u70BA\u66FF \u30B0\u30E9\u30D5 \u30C1\u30E3\u30FC\u30C8 \u5186 \u5186\u9AD8 \u5E02\u5834 \u682A \u682A\u4FA1",
    "\u2709\uFE0F": "\u5C01\u7B52 E\u30E1\u30FC\u30EB \u30E1\u30FC\u30EB \u624B\u7D19 \u90F5\u4FBF \u96FB\u5B50\u30E1\u30FC\u30EB",
    "\u{1F4E7}": "E\u30E1\u30FC\u30EB \u30E1\u30FC\u30EB \u5C01\u7B52 \u624B\u7D19 \u90F5\u4FBF \u96FB\u5B50\u30E1\u30FC\u30EB",
    "\u{1F4E8}": "\u30E1\u30FC\u30EB\u53D7\u4FE1\u4E2D E\u30E1\u30FC\u30EB \u53D7\u4FE1\u4E2D \u53D7\u4FE1\u7BB1 \u5C01\u7B52 \u624B\u7D19 \u96FB\u5B50\u30E1\u30FC\u30EB",
    "\u{1F4E9}": "\u30E1\u30FC\u30EB\u53D7\u4FE1 E\u30E1\u30FC\u30EB \u30E1\u30FC\u30EB\u9001\u4FE1 \u53D7\u4FE1 \u5C01\u7B52\u3068\u77E2\u5370 \u9001\u4FE1 \u96FB\u5B50\u30E1\u30FC\u30EB",
    "\u{1F4E4}": "\u9001\u4FE1\u30C8\u30EC\u30A4 E\u30E1\u30FC\u30EB \u30C8\u30EC\u30A4 \u7BB1 \u9001\u4FE1 \u9001\u4FE1\u7BB1 \u96FB\u5B50\u30E1\u30FC\u30EB",
    "\u{1F4E5}": "\u53D7\u4FE1\u30C8\u30EC\u30A4 E\u30E1\u30FC\u30EB \u30C8\u30EC\u30A4 \u53D7\u4FE1 \u53D7\u4FE1\u306A\u3057 \u53D7\u4FE1\u7BB1 \u7BB1 \u96FB\u5B50\u30E1\u30FC\u30EB",
    "\u{1F4E6}": "\u8377\u7269 \u5B85\u6025\u4FBF \u5B85\u914D\u4FBF \u5C0F\u5305 \u6BB5\u30DC\u30FC\u30EB \u7BB1 \u914D\u9001 \u914D\u9054",
    "\u{1F4EB}": "\u9589\u3058\u305F\u90F5\u4FBF\u53D7\u3051\uFF08\u624B\u7D19\u3042\u308A\uFF09 \u30DD\u30B9\u30C8 \u624B\u7D19\u3042\u308A \u90F5\u4FBF\u53D7\u3051 \u90F5\u4FBF\u7BB1 \u9589\u3058\u305F",
    "\u{1F4EA}": "\u9589\u3058\u305F\u90F5\u4FBF\u53D7\u3051\uFF08\u624B\u7D19\u306A\u3057\uFF09 \u30DD\u30B9\u30C8 \u624B\u7D19\u306A\u3057 \u90F5\u4FBF\u53D7\u3051 \u90F5\u4FBF\u7BB1 \u9589\u3058\u305F",
    "\u{1F4EC}": "\u958B\u3044\u305F\u90F5\u4FBF\u53D7\u3051\uFF08\u624B\u7D19\u3042\u308A\uFF09 \u30DD\u30B9\u30C8 \u624B\u7D19\u3042\u308A \u90F5\u4FBF\u53D7\u3051 \u90F5\u4FBF\u7BB1 \u958B\u3044\u305F",
    "\u{1F4ED}": "\u958B\u3044\u305F\u90F5\u4FBF\u53D7\u3051\uFF08\u624B\u7D19\u306A\u3057\uFF09 \u30DD\u30B9\u30C8 \u624B\u7D19\u306A\u3057 \u90F5\u4FBF\u53D7\u3051 \u90F5\u4FBF\u7BB1 \u958B\u3044\u305F",
    "\u{1F4EE}": "\u90F5\u4FBF\u30DD\u30B9\u30C8 \u30DD\u30B9\u30C8 \u624B\u7D19 \u90F5\u4FBF \u90F5\u4FBF\u7BB1",
    "\u{1F5F3}\uFE0F": "\u6295\u7968\u7BB1 \u6295\u7968 \u9078\u6319",
    "\u270F\uFE0F": "\u925B\u7B46 \u6587\u5177 \u6587\u623F\u5177",
    "\u2712\uFE0F": "\u30DA\u30F3\u5148 \u4E07\u5E74\u7B46 \u6587\u5177 \u6587\u623F\u5177",
